let fs   = require('fs');
let path = require('path');
let cfg  = require('../config');

const SUCC = 0;
const ERR = -1;

let fileHelper = {};

let mkdirs = dir => {
    try {
        if (fs.existsSync(dir)) return true;
        else {
            if (mkdirs(path.dirname(dir))) {
                fs.mkdirSync(dir);
                return true;
            }
        }
    } catch (err) {
        console.log('TAF-Config[File error]', 'Fun[mkdirs]', `Error[${err}]`);
    }
};

fileHelper.write = (configInfo, content) => {
    let opts = {
        encoding: cfg.file.encoding
    };


    let dir = cfg.file.path.tafConfig.replace('%srv%', `${configInfo.appname}.${configInfo.servername}`);
    if(process.env.TAF_CONFIG)
    {
        let envPath = path.resolve(process.env.TAF_CONFIG, "../../../");
        dir = `${envPath}/${configInfo.appname}.${configInfo.servername}/data`;
    }
    let file = dir + '/' + configInfo.filename;
    mkdirs(dir);

    return new Promise((resolve, reject) => {
        fs.writeFile(file, content, opts, err => {
            if (err) {
                console.log('TAF-Config[File error]', 'Fun[write]', `Error[${err}]`);
                reject(ERR);
            } else resolve(SUCC);
        });
    });
};

fileHelper.read = configInfo => {
    let opts = {
        encoding: cfg.file.encoding
    };
    let dir = cfg.file.path.tafConfig.replace('%srv%', `${configInfo.appname}.${configInfo.servername}`);
    if(process.env.TAF_CONFIG)
    {
        let envPath = path.resolve(process.env.TAF_CONFIG, "../../../");
        dir = `${envPath}/${configInfo.appname}.${configInfo.servername}/data`;
    }
    let file = dir + '/' + configInfo.filename;

    return new Promise((resolve, reject) => {
        fs.readFile(file, opts, (err, data) => {
            if (err) {
                console.log('TAF-Config[File error]', 'Fun[read]', `Error[${err}]`);
                reject(err);
            } else resolve(data);
        });
    });
};

module.exports = fileHelper;
